import {
  array,
  boolean,
  decodeJson,
  json,
  mutation,
  number,
  object,
  query,
  router,
  string,
} from "apps";

const base = "https://docs.googleapis.com/v1/documents";

/** The router's metadata, shared with packages/google. */
export const meta = {
  title: "Google Docs",
  description:
    "Read Google Docs as JSON or plain text, create documents, and edit them: insert, replace and delete text, styles, lists, tables, images and raw batchUpdate requests.",
  instructions:
    "Indexes are UTF-16 code units; the body starts at 1. Call getText or getDocument first to find indexes. Within one batchUpdate, requests apply in order, so edit later positions first. Pass requiredRevisionId (from getDocument) to fail instead of overwriting concurrent edits.",
};

type Fetch = typeof fetch;

const Location = { index: number(), tabId: string().optional() };
const Range = { startIndex: number(), endIndex: number(), tabId: string().optional() };
const documentId = string({ minLength: 1 });

export function tools(token: string, fetcher: Fetch, signal: AbortSignal | undefined) {
  const call = async (path: string, init: { method?: string; body?: unknown; search?: Record<string, string | undefined> } = {}) => {
    const url = new URL(`${base}${path}`);
    for (const [key, value] of Object.entries(init.search ?? {})) if (value !== undefined) url.searchParams.set(key, value);
    const response = await fetcher(url.toString(), {
      method: init.method ?? "GET",
      signal,
      headers: { Authorization: `Bearer ${token}`, "content-type": "application/json" },
      body: init.body === undefined ? undefined : JSON.stringify(init.body),
    });
    return decodeJson(response, json());
  };
  const batch = (id: string, requests: unknown[], requiredRevisionId?: string) =>
    call(`/${encodeURIComponent(id)}:batchUpdate`, {
      method: "POST",
      body: { requests, ...(requiredRevisionId ? { writeControl: { requiredRevisionId } } : {}) },
    });
  const revision = string().optional();

  return router({
    getDocument: query(
      {
        description:
          "Get a document as Google Docs JSON: title, revisionId, body structure with character indexes, styles, lists, named ranges.",
        input: object({
          documentId,
          includeTabsContent: boolean().optional(),
          suggestionsViewMode: string().optional(),
        }),
      },
      async (_ctx, { documentId, includeTabsContent, suggestionsViewMode }) =>
        call(`/${encodeURIComponent(documentId)}`, {
          search: { includeTabsContent: includeTabsContent === undefined ? undefined : String(includeTabsContent), suggestionsViewMode },
        }),
    ),
    getText: query(
      {
        description:
          "Get the plain text of a document's body, with the start index of each paragraph so edits can target it.",
        input: object({ documentId, tabId: string().optional() }),
      },
      async (_ctx, { documentId, tabId }) => {
        const doc = (await call(`/${encodeURIComponent(documentId)}`, {
          search: { includeTabsContent: tabId ? "true" : undefined },
        })) as Record<string, any>;
        const tab = tabId ? findTab(doc.tabs ?? [], tabId) : undefined;
        if (tabId && !tab) throw new Error(`Tab ${tabId} was not found in document ${documentId}`);
        const content = (tab?.documentTab ?? doc).body?.content ?? [];
        const paragraphs: { startIndex: number; text: string }[] = [];
        collect(content, paragraphs);
        return {
          title: doc.title ?? "",
          revisionId: doc.revisionId ?? null,
          text: paragraphs.map((p) => p.text).join(""),
          paragraphs,
        };
      },
    ),
    createDocument: mutation(
      {
        description: "Create a blank document with the given title. Returns the new document including its documentId.",
        input: object({ title: string() }),
      },
      async (_ctx, { title }) => call("", { method: "POST", body: { title } }),
    ),
    batchUpdate: mutation(
      {
        description:
          "Apply raw documents.batchUpdate requests (an array of Request objects, e.g. insertText, updateTextStyle). Indexes refer to the document before the batch; requests apply in order, so edit from the end of the document backwards. Use for anything the other tools do not cover.",
        input: object({ documentId, requests: array(json()), requiredRevisionId: revision }),
      },
      async (_ctx, { documentId, requests, requiredRevisionId }) => batch(documentId, [...requests], requiredRevisionId),
    ),
    appendText: mutation(
      {
        description: "Append text at the end of the document body (or of a tab).",
        input: object({ documentId, text: string(), tabId: string().optional() }),
      },
      async (_ctx, { documentId, text, tabId }) =>
        batch(documentId, [{ insertText: { text, endOfSegmentLocation: tabId ? { tabId } : {} } }]),
    ),
    insertText: mutation(
      {
        description: "Insert text at a character index (1 is the start of the body).",
        input: object({ documentId, text: string(), ...Location, requiredRevisionId: revision }),
      },
      async (_ctx, { documentId, text, index, tabId, requiredRevisionId }) =>
        batch(documentId, [{ insertText: { text, location: { index, ...(tabId ? { tabId } : {}) } } }], requiredRevisionId),
    ),
    replaceAllText: mutation(
      {
        description: "Replace every occurrence of a string in the document.",
        input: object({
          documentId,
          find: string({ minLength: 1 }),
          replaceWith: string(),
          matchCase: boolean().optional(),
        }),
      },
      async (_ctx, { documentId, find, replaceWith, matchCase }) =>
        batch(documentId, [
          { replaceAllText: { containsText: { text: find, matchCase: matchCase ?? false }, replaceText: replaceWith } },
        ]),
    ),
    deleteContentRange: mutation(
      {
        description: "Delete the content between startIndex (inclusive) and endIndex (exclusive).",
        input: object({ documentId, ...Range, requiredRevisionId: revision }),
      },
      async (_ctx, { documentId, startIndex, endIndex, tabId, requiredRevisionId }) =>
        batch(documentId, [{ deleteContentRange: { range: { startIndex, endIndex, ...(tabId ? { tabId } : {}) } } }], requiredRevisionId),
    ),
    updateTextStyle: mutation(
      {
        description:
          "Style a text range. textStyle is a Docs TextStyle object (bold, italic, underline, strikethrough, fontSize, foregroundColor, link, ...); fields is the field mask naming which to set, e.g. \"bold,italic\".",
        input: object({ documentId, ...Range, textStyle: json(), fields: string({ minLength: 1 }) }),
      },
      async (_ctx, { documentId, startIndex, endIndex, tabId, textStyle, fields }) =>
        batch(documentId, [
          { updateTextStyle: { range: { startIndex, endIndex, ...(tabId ? { tabId } : {}) }, textStyle, fields } },
        ]),
    ),
    updateParagraphStyle: mutation(
      {
        description:
          "Style the paragraphs in a range. paragraphStyle is a Docs ParagraphStyle (namedStyleType such as HEADING_1, alignment, lineSpacing, ...); fields is the field mask.",
        input: object({ documentId, ...Range, paragraphStyle: json(), fields: string({ minLength: 1 }) }),
      },
      async (_ctx, { documentId, startIndex, endIndex, tabId, paragraphStyle, fields }) =>
        batch(documentId, [
          { updateParagraphStyle: { range: { startIndex, endIndex, ...(tabId ? { tabId } : {}) }, paragraphStyle, fields } },
        ]),
    ),
    createParagraphBullets: mutation(
      {
        description: "Turn the paragraphs in a range into a bulleted or numbered list.",
        input: object({ documentId, ...Range, bulletPreset: string().default("BULLET_DISC_CIRCLE_SQUARE") }),
      },
      async (_ctx, { documentId, startIndex, endIndex, tabId, bulletPreset }) =>
        batch(documentId, [
          { createParagraphBullets: { range: { startIndex, endIndex, ...(tabId ? { tabId } : {}) }, bulletPreset } },
        ]),
    ),
    insertTable: mutation(
      {
        description: "Insert an empty table at an index.",
        input: object({ documentId, rows: number(), columns: number(), ...Location }),
      },
      async (_ctx, { documentId, rows, columns, index, tabId }) =>
        batch(documentId, [{ insertTable: { rows, columns, location: { index, ...(tabId ? { tabId } : {}) } } }]),
    ),
    insertInlineImage: mutation(
      {
        description: "Insert an image from a public URL at an index.",
        input: object({
          documentId,
          uri: string({ minLength: 1 }),
          ...Location,
          widthPt: number().optional(),
          heightPt: number().optional(),
        }),
      },
      async (_ctx, { documentId, uri, index, tabId, widthPt, heightPt }) => {
        if ((widthPt === undefined) !== (heightPt === undefined)) {
          throw new Error("Provide widthPt and heightPt together, or neither");
        }
        if ((widthPt !== undefined && widthPt <= 0) || (heightPt !== undefined && heightPt <= 0)) {
          throw new Error("widthPt and heightPt must be positive");
        }
        return batch(documentId, [
          {
            insertInlineImage: {
              uri,
              location: { index, ...(tabId ? { tabId } : {}) },
              ...(widthPt !== undefined && heightPt !== undefined
                ? { objectSize: { width: { magnitude: widthPt, unit: "PT" }, height: { magnitude: heightPt, unit: "PT" } } }
                : {}),
            },
          },
        ]);
      },
    ),
    insertPageBreak: mutation(
      {
        description: "Insert a page break at an index.",
        input: object({ documentId, ...Location }),
      },
      async (_ctx, { documentId, index, tabId }) =>
        batch(documentId, [{ insertPageBreak: { location: { index, ...(tabId ? { tabId } : {}) } } }]),
    ),
    createNamedRange: mutation(
      {
        description: "Give a text range a name so it can be found again after edits.",
        input: object({ documentId, name: string({ minLength: 1 }), ...Range }),
      },
      async (_ctx, { documentId, name, startIndex, endIndex, tabId }) =>
        batch(documentId, [{ createNamedRange: { name, range: { startIndex, endIndex, ...(tabId ? { tabId } : {}) } } }]),
    ),
    deleteNamedRange: mutation(
      {
        description: "Delete named ranges by name (all with that name) or by id.",
        input: object({ documentId, name: string().optional(), namedRangeId: string().optional() }),
      },
      async (_ctx, { documentId, name, namedRangeId }) => {
        if ((name === undefined) === (namedRangeId === undefined)) {
          throw new Error("Provide exactly one of name or namedRangeId");
        }
        return batch(documentId, [{ deleteNamedRange: namedRangeId !== undefined ? { namedRangeId } : { name } }]);
      },
    ),
    replaceNamedRangeContent: mutation(
      {
        description: "Replace the content of every range with the given name.",
        input: object({ documentId, name: string({ minLength: 1 }), text: string() }),
      },
      async (_ctx, { documentId, name, text }) =>
        batch(documentId, [{ replaceNamedRangeContent: { namedRangeName: name, text } }]),
    ),
  });
}

function findTab(tabs: any[], id: string): any {
  for (const tab of tabs) {
    if (tab.tabProperties?.tabId === id) return tab;
    const child = findTab(tab.childTabs ?? [], id);
    if (child) return child;
  }
  return undefined;
}

function collect(content: any[], out: { startIndex: number; text: string }[]) {
  for (const element of content) {
    if (element.paragraph) {
      const text = (element.paragraph.elements ?? []).map((e: any) => e.textRun?.content ?? "").join("");
      out.push({ startIndex: element.startIndex ?? 0, text });
    } else if (element.table) {
      for (const row of element.table.tableRows ?? [])
        for (const cell of row.tableCells ?? []) collect(cell.content ?? [], out);
    } else if (element.tableOfContents) {
      collect(element.tableOfContents.content ?? [], out);
    }
  }
}
